package org.metaeffekt.kontinuum.runtime.models.shared;

import lombok.Data;

/**
 * Execution overrides supplied by the caller when generating a pipeline.
 */
@Data
public class OverwriteOptions {

    private Boolean forceDisablePortfolioManager = false;
    private Boolean forceEnableLocalResolve = false;
    private Boolean forceEnableLocalScan = false;

    // The methods below simply provide more sensible method names compared to the default getters generated by Lombok

    public boolean isForceDisablePortfolioManager() {
        return Boolean.TRUE.equals(forceDisablePortfolioManager);
    }

    public boolean isForceEnableLocalResolve() {
        return Boolean.TRUE.equals(forceEnableLocalResolve);
    }

    public boolean isForceEnableLocalScan() {
        return Boolean.TRUE.equals(forceEnableLocalScan);
    }
}
